// A tiny event bus: the subject keeps a set of listeners.
function createEventBus() {
  const listeners = new Set()
  return {
    subscribe(listener) {
      listeners.add(listener)
      return () => listeners.delete(listener)   // call this to unsubscribe
    },
    publish(event) {
      for (const listener of listeners) listener(event)
    }
  }
}

const orderShipped = createEventBus()

// shipOrder knows nothing about email, analytics or the warehouse.
function shipOrder(id) {
  orderShipped.publish({ id })
}

orderShipped.subscribe((e) => console.log(`email: order ${e.id} shipped`))
const stopAnalytics = orderShipped.subscribe((e) => console.log(`analytics: order ${e.id}`))

shipOrder(1)

