class AcmePayAdapter:
    """Adapter: makes the vendor SDK look like our gateway."""
    def __init__(self, client):
        self.client = client

    def charge(self, amount_cents, customer_id):
        result = self.client.create_payment(
            amount={"value": f"{amount_cents / 100:.2f}", "currency": "USD"},
            payer=customer_id)
        return result["payment_id"]          # our type, not theirs

class LoggingGateway:
    """Decorator: same interface, adds logging."""
    def __init__(self, inner, log):
        self.inner, self.log = inner, log

    def charge(self, amount_cents, customer_id):
        self.log.info("charging %s %d cents", customer_id, amount_cents)
        return self.inner.charge(amount_cents, customer_id)

# A Python decorator: a function that wraps a function
import functools, time

def timed(func):
    @functools.wraps(func)                  # keep name and docstring
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        print(f"{func.__name__}: {time.perf_counter() - start:.3f}s")
        return result                       # forget this: callers get None
    return wrapper

# Singleton style: the dependency hides inside the method
class ReportService:
    def monthly_total(self):
        return Database.instance().query("SELECT SUM(total) FROM orders")

# Dependency injection: the dependency is a visible parameter
class ReportService:
    def __init__(self, db):
